      ],
      "claim": "Unknown-tree recovery releases a panel member when a live reviewer descends through a dead, unrecorded intermediate process, because direct-parent scans cannot find it and the panel path omits the machine-wide scan.",
      "trigger": "After denied enumeration and an unconfirmed kill, the recorded bridge and launcher are gone, an unrecorded intermediate parent has exited, and its reviewer child remains alive.",
      "evidence": [
        {
          "kind": "read-code",
          "reference": "plugins/codex-consult/scripts/codex-consult-common.ps1:Find-CodexProcesses",
          "observation": "The by-parent scan matches only processes whose current ParentProcessId equals the supplied recorded PID."
        },
        {
          "kind": "read-code",
          "reference": "plugins/codex-consult/scripts/codex-consult-common.ps1:10207-10217",
          "observation": "Panel records omit the machine-wide scan and return inactive after the recorded-parent scans find nothing."
        },
        {
          "kind": "ran-command",
          "reference": "Read-only Test-PendingActive replay using the actual Find-CodexProcesses function and a mocked Windows process table",
          "observation": "A live codex.exe with a dead, unrecorded parent produced Active=false for a panel record. Removing the panel field produced Active=true for the same process table."
        }
      ],
      "verification": "Run a panel recovery fixture containing a surviving reviewer beneath a dead, unrecorded intermediate parent; require recovery to remain active and prevent another launch.",
      "remedy": "Do not release an unknown panel tree solely from clean direct-parent scans. Preserve the uncertainty until reliable ownership tracking establishes termination or the operator explicitly clears it; merely adding a global scan must also account for live sibling reviewers.",
      "supersedes": [
        "F30-1"
      ]
    },
    {
      "severity": "minor",
      "locations": [
        {
          "path": "plugins/codex-consult/scripts/codex-consult-common.ps1",
          "line": 11960
        },
        {
          "path": "plugins/codex-consult/scripts/codex-consult-common.ps1",
          "line": 12061
        },
        {
          "path": "plugins/codex-consult/scripts/codex-consult-common.ps1",
          "line": 12103
        }
      ],
      "claim": "The {name, bytes} fold marker cannot distinguish a recreated legacy file whose length equals or exceeds the deleted generation, so new diagnostic counter lines can still be skipped and deleted.",
      "trigger": "A fold deletes the legacy file, then crashes before clearing its committed marker; an older producer recreates that filename with at least the recorded byte length before recovery.",
      "evidence": [
        {
          "kind": "read-code",
          "reference": "plugins/codex-consult/scripts/codex-consult-common.ps1:Read-SharedTextFrom, Merge-TelemetryNotSpooled",
          "observation": "Only shorter files are treated as replacements. Equal or longer files are treated as already accounted through the recorded offset."
        },
        {
          "kind": "ran-command",
          "reference": "Read-only telemetry replay using MemoryStream-backed files",
          "observation": "An equal-length replacement containing one new line returned Status=0 and NewlyFolded=0. A longer replacement containing two new lines returned Status=1 and NewlyFolded=1. Both were held for deletion; the same-file append control correctly counted one appended line."
        }
      ],
      "verification": "Interrupt after legacy-file deletion but before marker cleanup, recreate the filename with equal-length and longer new contents, then require all replacement lines to be accounted exactly once.",
      "remedy": "Use a unique staged filename or another reliable generation identity for committed fold contents. Do not infer generation identity from length; retain offset handling only after establishing that it is the same generation.",
      "supersedes": [
        "F30-2"
      ]
    }
  ],
